#!/usr/bin/env bash
# Type-check the bar's QML the way quickshell will actually see it.
#
# The sources in modules/home/wayland/quickshell/qml are not lintable on their
# own: Config.qml is generated by Nix and is not among them, and the singleton
# needs a qmldir that the runtime never requires. So put the sources and the
# generated Config.qml side by side, lint that copy, and take every import path
# out of the same nixpkgs the bar runs against.
#
# Nothing is built for the host itself: the framework's config is x86_64-only,
# so building it fails with a platform mismatch on an aarch64 host. The bar
# derivation passes its qml/ source and Config.qml through instead, and both
# are read by evaluation alone. qmllint and quickshell come from the flake's
# nixpkgs for this machine, which matches the bar's only while default.nix
# uses plain pkgs.quickshell; an override there has to be repeated here.
#
# Usage: .claude/skills/quickshell-bar/lint.sh [file.qml ...]
# With no arguments every file in the config is linted.
set -euo pipefail

host="${QUICKSHELL_LINT_HOST:-framework}"
user="${QUICKSHELL_LINT_USER:-lbischof}"
bar=".#nixosConfigurations.$host.config.home-manager.users.$user.programs.quickshell.configs.bar"

cd "$(git rev-parse --show-toplevel)"

native() { nix build --no-link --print-out-paths --inputs-from . "nixpkgs#$1"; }
qtdeclarative="$(native qt6.qtdeclarative)"
quickshell="$(native quickshell)"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
qml="$(nix eval --raw "$bar.qml")"
cp "$qml"/*.qml "$work"/
nix eval --raw "$bar.config.text" >"$work/Config.qml"
# qmllint resolves a pragma Singleton only through a qmldir; quickshell finds
# it by directory alone, so the repo has none to copy. Every singleton has to
# be listed, generated Config.qml included -- one left out is reported against
# its own file as "not declared as singleton in qmldir", which reads like a
# finding in the file rather than a gap in this script.
{
  echo "module bar"
  for f in "$work"/*.qml; do
    if grep -q '^pragma Singleton' "$f"; then
      echo "singleton $(basename "$f" .qml) 1.0 $(basename "$f")"
    fi
  done
} >"$work/qmldir"

if [ "$#" -gt 0 ]; then
  targets=()
  for f in "$@"; do targets+=("$work/$(basename "$f")"); done
else
  targets=("$work"/*.qml)
fi

# Both -I paths are load-bearing: drop either and every type fails to resolve,
# burying the real findings under hundreds of import warnings.
"$qtdeclarative/bin/qmllint" \
  -I "$work" \
  -I "$qtdeclarative/lib/qt-6/qml" \
  -I "$quickshell/lib/qt-6/qml" \
  "${targets[@]}"
